/**
 * SwapEngine 0x quotes show the fee the RELAY set and verified — never a local
 * estimate. The relay (provian-backend routes/swap-proxy.ts) adds 25 bps to every
 * 0x request and returns `provian_fee` only after verifying 0x's answer; 0x's
 * `buyAmount` is already net of every fee, so it is exactly what the user receives.
 * The response body below is a real relay-shaped 0x v2 answer (Base, 0.01 ETH →
 * USDC, 2026-09-25) with the relay's `provian_fee` attached.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';

vi.mock('../../AppModeManager', () => ({ assertWalletEnabled: vi.fn() }));
vi.mock('../../simulation/SimulationEngine', () => ({ default: {} }));
vi.mock('../../provenance/ProvenanceEnvelopeManager', () => ({ default: {} }));
vi.mock('../../../services/ProxyConfig', () => ({
    default: {
        getZeroXUrl: vi.fn(async (endpoint: string) => `https://relay.test/api/proxy/zerox/${endpoint}`),
        getProxyHeaders: vi.fn(async () => ({ Authorization: 'Bearer t' })),
    },
}));

import engine from '../SwapEngine';

const ZEROX = {
    "buyToken": "0x833589fcd6edb6e08f4c7c32d4f71b54bda02913",
    "buyAmount": "27049545",
    "fees": {
        "integratorFee": {
            "amount": "67895",
            "token": "0x833589fcd6edb6e08f4c7c32d4f71b54bda02913",
            "type": "volume"
        },
        "integratorFees": [
            {
                "amount": "67895",
                "token": "0x833589fcd6edb6e08f4c7c32d4f71b54bda02913",
                "type": "volume"
            }
        ],
        "zeroExFee": {
            "amount": "40737",
            "token": "0x833589fcd6edb6e08f4c7c32d4f71b54bda02913",
            "type": "volume"
        },
        "gasFee": null
    },
    "transaction": {
        "to": "0x0000000000001ff3684f28c67538d4d072c22734",
        "data": ""
    }
};
const TAKER = '0xd8da6bf26964af9d7eed9e03e53415d37aa96045';

function respond(body: unknown) {
    return vi.fn(async () => ({ ok: true, status: 200, json: async () => body }));
}

beforeEach(() => {
    engine.stopQuoteCleanup();
});

describe('SwapEngine 0x quote — the relay-verified fee', () => {
    it('shows the exact Provian fee in the buy token, 0x\'s own fee separately, and buyAmount as received', async () => {
        const body = { ...ZEROX, sellAmount: '10000000000000000', provian_fee: { bps: 25, amount: ZEROX.fees.integratorFee.amount, token: ZEROX.buyToken } };
        vi.stubGlobal('fetch', respond(body));
        const q = await engine.getQuote('Base', 'ETH', 'USDC', '0.01', 0.5, TAKER, 'Base');
        expect(q).not.toBeNull();
        expect(q!.isMock).toBeFalsy();
        expect(q!.provianFee).toBe('0.067895');
        expect(q!.provianFeeToken).toBe('USDC');
        expect(q!.provianFeeUsd).toBeCloseTo(0.067895);
        expect(q!.netToAmount).toBe('27.049545'); // buyAmount, already net
        expect(q!.otherFees).toEqual([{ kind: 'zerox', amount: '0.040737', token: 'USDC' }]);
        // The app sends routing fields only; the relay sets the fee.
        const url = new URL((globalThis.fetch as unknown as { mock: { calls: string[][] } }).mock.calls[0][0]);
        expect(url.searchParams.has('swapFeeBps')).toBe(false);
        expect(url.searchParams.has('swapFeeRecipient')).toBe(false);
        vi.unstubAllGlobals();
    });

    it('RED: a 0x answer without the relay-verified fee is never presented as a live quote', async () => {
        vi.stubGlobal('fetch', respond({ ...ZEROX, sellAmount: '10000000000000000' }));
        const q = await engine.getQuote('Base', 'ETH', 'USDC', '0.01', 0.5, TAKER, 'Base');
        // no quote at all — never a mock price the screen could show.
        expect(q).toBeNull();
        vi.unstubAllGlobals();
    });
});
